CREATE TABLE users (
  id CHAR(36) PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  phone_e164 VARCHAR(20) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  status ENUM('active','blocked','deleted') NOT NULL DEFAULT 'active',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);
CREATE TABLE roles (id CHAR(36) PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE permissions (id CHAR(36) PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE role_permissions (role_id CHAR(36) NOT NULL, permission_id CHAR(36) NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE user_global_roles (user_id CHAR(36) NOT NULL, role_id CHAR(36) NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE companies (id CHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, status ENUM('active','blocked') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE company_members (id CHAR(36) PRIMARY KEY, company_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, role_id CHAR(36) NOT NULL, status ENUM('active','revoked') NOT NULL DEFAULT 'active', UNIQUE KEY uq_company_member(company_id,user_id), FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE professional_profiles (user_id CHAR(36) PRIMARY KEY, vehicle_type VARCHAR(40), availability ENUM('offline','available','busy') NOT NULL DEFAULT 'offline', location_consent_at TIMESTAMP NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE company_professionals (company_id CHAR(36) NOT NULL, professional_user_id CHAR(36) NOT NULL, status ENUM('active','revoked') NOT NULL DEFAULT 'active', PRIMARY KEY(company_id,professional_user_id), FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(professional_user_id) REFERENCES users(id));
CREATE TABLE places (id CHAR(36) PRIMARY KEY, company_id CHAR(36) NULL, nickname VARCHAR(120) NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, notes TEXT NULL, created_by CHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(created_by) REFERENCES users(id), INDEX ix_places_company(company_id));
CREATE TABLE depots (id CHAR(36) PRIMARY KEY, place_id CHAR(36) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(place_id) REFERENCES places(id));
CREATE TABLE company_depots (company_id CHAR(36) NOT NULL, depot_id CHAR(36) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(company_id,depot_id), FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(depot_id) REFERENCES depots(id));
CREATE TABLE professional_locations (professional_user_id CHAR(36) PRIMARY KEY, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, accuracy_m DECIMAL(8,2), recorded_at TIMESTAMP NOT NULL, FOREIGN KEY(professional_user_id) REFERENCES users(id));
CREATE TABLE orders (id CHAR(36) PRIMARY KEY, company_id CHAR(36) NOT NULL, created_by CHAR(36) NOT NULL, pickup_place_id CHAR(36) NOT NULL, destination_depot_id CHAR(36) NOT NULL, description TEXT NOT NULL, pickup_contact VARCHAR(160), notes TEXT, status ENUM('draft','open','accepted','arrived_pickup','collected','delivered','cancelled') NOT NULL DEFAULT 'draft', accepted_by CHAR(36) NULL, accepted_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(pickup_place_id) REFERENCES places(id), FOREIGN KEY(destination_depot_id) REFERENCES depots(id), FOREIGN KEY(accepted_by) REFERENCES users(id), INDEX ix_orders_company_status(company_id,status));
CREATE TABLE order_offers (id CHAR(36) PRIMARY KEY, order_id CHAR(36) NOT NULL, professional_user_id CHAR(36) NOT NULL, status ENUM('offered','accepted','rejected','expired') NOT NULL DEFAULT 'offered', offered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, responded_at TIMESTAMP NULL, UNIQUE KEY uq_offer(order_id,professional_user_id), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(professional_user_id) REFERENCES users(id));
CREATE TABLE order_events (id CHAR(36) PRIMARY KEY, order_id CHAR(36) NOT NULL, actor_user_id CHAR(36) NOT NULL, from_status VARCHAR(30), to_status VARCHAR(30) NOT NULL, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, metadata_json JSON, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(actor_user_id) REFERENCES users(id), INDEX ix_order_events_order(order_id,occurred_at));
CREATE TABLE order_attachments (id CHAR(36) PRIMARY KEY, order_id CHAR(36) NOT NULL, uploaded_by CHAR(36) NOT NULL, storage_key VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes INT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(uploaded_by) REFERENCES users(id));
CREATE TABLE device_tokens (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, platform VARCHAR(20) NOT NULL, token VARCHAR(512) NOT NULL, revoked_at TIMESTAMP NULL, UNIQUE KEY uq_device_token(token), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE notifications (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, order_id CHAR(36) NULL, type VARCHAR(50) NOT NULL, status ENUM('pending','sent','failed') NOT NULL DEFAULT 'pending', sent_at TIMESTAMP NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE audit_logs (id CHAR(36) PRIMARY KEY, actor_user_id CHAR(36) NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id CHAR(36) NOT NULL, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, metadata_json JSON, FOREIGN KEY(actor_user_id) REFERENCES users(id), INDEX ix_audit_entity(entity_type,entity_id));
